//! Oracle tier: reads artifacts regenerated by `scripts/regen-fixtures.py`
//! (tools/fixtures/langlibelk-language*.toml, docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
#[path = "../examples/format-oracle.rs"]
#[allow(dead_code)]
mod oracle;

#[test]
fn pinned_go_formatter_regressions() {
    let fixture: serde_json::Value = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/format.json"
    ))
    .unwrap();
    let requests = fixture["requests"].as_array().unwrap();
    let expected = fixture["reference"].as_array().unwrap();
    assert_eq!(requests.len(), expected.len());
    for (index, (request, expected)) in requests.iter().zip(expected).enumerate() {
        let actual = oracle::evaluate(serde_json::from_value(request.clone()).unwrap());
        assert_eq!(&actual, expected, "formatter case {index}: {request}");
    }
}
